//! Benchmarks for the performance building blocks.
//!
//! Each group pits a Vulcan primitive against the naive alternative it replaces, so a regression
//! shows up as a shrinking gap. Run locally with `cargo bench`; CI runs them under CodSpeed,
//! which counts instructions instead of measuring wall time, so results are stable enough to gate
//! pull requests.

// `criterion_group!` and `criterion_main!` expand to undocumented items that read env vars.
#![allow(missing_docs, clippy::disallowed_methods, reason = "code generated by criterion macros")]
// Benchmark inputs are small synthetic integers, and the benchmark closures return their result
// so the optimizer cannot remove the work.
#![allow(
    clippy::cast_possible_truncation,
    unused_results,
    reason = "synthetic inputs; results are consumed by `black_box`"
)]

extern crate alloc;

use alloc::collections::BTreeMap;
use core::{hint::black_box, str};
use criterion::{BenchmarkId, Criterion, criterion_group, criterion_main};
use vulcan::{
    arena::{Bump, BumpExtension as _},
    bytes::{Cursor, StaticFinder, is_id_continue, is_whitespace},
    division::Divide as _,
    intern::Interner,
    sync::{Parallelism, par_try_map},
};

/// A synthetic source mixing identifiers, whitespace and block comments.
fn bench_scan_source(word_count: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(word_count * 16);
    for i in 0..word_count {
        out.extend_from_slice(format!("ident_{} ", i.remainder(97)).as_bytes());
        if i.remainder(8) == 0 {
            out.extend_from_slice(b"/* a comment that spans some bytes */ ");
        }
    }
    out
}

/// The end of a block comment, searched with a searcher built once.
static BLOCK_END: StaticFinder = StaticFinder::new(b"*/");

/// Counts the identifiers of `input`, skipping whitespace and block comments. A free function over
/// a plain slice, so the hot loop stays out of the benchmark closures.
fn bench_scan_count_identifiers(input: &[u8]) -> u32 {
    let mut cursor = Cursor::new(input);
    let mut identifier_count = 0_u32;
    // Bounded: every iteration before the end consumes at least one byte.
    for _ in 0..=input.len() {
        if cursor.is_eof() {
            break;
        }
        cursor.eat_while(is_whitespace);
        if cursor.eat_prefix(b"/*") {
            cursor.skip_past_finder(BLOCK_END.get());
        } else {
            if cursor.eat_while(is_id_continue).is_empty() {
                cursor.bump();
            } else {
                identifier_count += 1;
            }
        }
    }
    assert!(cursor.is_eof(), "the bound covers one byte per iteration");
    identifier_count
}

/// Compares the table-driven cursor with a scan over `char`s.
fn bench_scan(criterion: &mut Criterion) {
    let input = bench_scan_source(4096);
    let mut group = criterion.benchmark_group("scan");
    group.bench_function("cursor_table", |bencher| {
        bencher.iter(|| bench_scan_count_identifiers(black_box(&input)));
    });
    group.bench_function("char_naive", |bencher| {
        bencher.iter(|| {
            let text = str::from_utf8(black_box(&input)).map_or("", |text| text);
            text.split_whitespace()
                .filter(|word| word.chars().all(|letter| letter.is_alphanumeric() || letter == '_'))
                .count()
        });
    });
    group.finish();
}

/// Compares the arena interner with a `BTreeMap` of owned strings.
fn bench_intern(criterion: &mut Criterion) {
    let words: Vec<String> =
        (0..10_000_u32).map(|i| format!("ident_{}", i.remainder(512))).collect();
    let mut group = criterion.benchmark_group("intern");
    group.bench_function("interner", |bencher| {
        bencher.iter(|| {
            let arena = Bump::with_fixed_capacity(16 * 1024);
            let mut interner = Interner::with_capacity(&arena, 512);
            for word in &words {
                black_box(interner.intern(word));
            }
            interner.len()
        });
    });
    group.bench_function("btreemap_string", |bencher| {
        bencher.iter(|| {
            let mut map = BTreeMap::new();
            for word in &words {
                let next = map.len();
                black_box(*map.entry(word.clone()).or_insert(next));
            }
            map.len()
        });
    });
    group.finish();
}

/// Compares nodes allocated in an arena with nodes boxed one by one.
fn bench_alloc(criterion: &mut Criterion) {
    let mut group = criterion.benchmark_group("alloc_nodes");
    for node_count in [1_000_u32, 10_000] {
        group.bench_with_input(
            BenchmarkId::new("bump", node_count),
            &node_count,
            |bencher, &count| {
                bencher.iter(|| {
                    let arena = Bump::with_fixed_capacity(count * 16);
                    let total: usize = (0..count).map(|i| arena.allocate_exact([i; 4]).len()).sum();
                    total
                });
            },
        );
        group.bench_with_input(
            BenchmarkId::new("box", node_count),
            &node_count,
            |bencher, &count| {
                bencher.iter(|| {
                    let nodes: Vec<Box<[u32]>> =
                        (0..count).map(|i| vec![i; 4].into_boxed_slice()).collect();
                    nodes.len()
                });
            },
        );
    }
    group.finish();
}

/// Compares the serial and the parallel paths of `par_try_map`.
fn bench_par(criterion: &mut Criterion) {
    let items: Vec<u64> = (0..256).collect();
    let work = |seed: u64| {
        Ok::<_, ()>((0..2_000_u64).fold(seed, |state, step| state.wrapping_mul(31) ^ step))
    };
    let mut group = criterion.benchmark_group("par_try_map");
    for (name, parallelism) in
        [("serial", Parallelism::Serial), ("parallel", Parallelism::Parallel)]
    {
        group.bench_function(name, |bencher| {
            bencher.iter(|| par_try_map(parallelism, black_box(items.clone()), work));
        });
    }
    group.finish();
}

criterion_group!(benches, bench_scan, bench_intern, bench_alloc, bench_par);
criterion_main!(benches);
